sweep_cost.driver:
//! #1681 sweep cost (not committed): census m1/m3 key stream on the 8-byte trie.
//! mode one1m: one sweep at 1,000,000 held. mode one_m3: one sweep at the end of
//! 4,194,304 inserts through the 1M window. mode periodic_s1 / periodic_s3: a sweep
//! every 65,536 inserts. Callgrind toggles on `sweep`.
use expanse_trie::map::ExpanseMap;
fn mix32(mut x: u32) -> u32 { x ^= x >> 16; x = x.wrapping_mul(0x7feb352d); x ^= x >> 15; x = x.wrapping_mul(0x846ca68b); x ^= x >> 16; x }
#[inline(never)]
fn sweep(m: &mut ExpanseMap) -> usize { std::hint::black_box(m.shrink_to_fit()) }
fn main() {
    let mode = std::env::args().nth(1).unwrap();
    let n: usize = match mode.as_str() { "one1m" | "periodic_s1" => 1 << 20, _ => 1 << 22 };
    let window = 1_000_000usize; let seed: u32 = 4242; let ports = [80u16, 443, 8080, 8443];
    let w: Vec<u64> = (0..n).map(|i| { let mut k = [0u8; 8];
        k[..4].copy_from_slice(&mix32((i as u32).wrapping_add(seed.wrapping_mul(0x9e3779b9))).to_be_bytes());
        k[4..6].copy_from_slice(&ports[i & 3].to_be_bytes()); u64::from_be_bytes(k) }).collect();
    let periodic = mode.starts_with("periodic");
    let mut m = ExpanseMap::new(); let mut sweeps = 0usize; let mut released = 0usize;
    for i in 0..n {
        if i >= window { assert!(m.remove(w[i - window]).is_some()); }
        if periodic && i % 65_536 == 65_535 { released += sweep(&mut m); sweeps += 1; }
        m.insert(w[i], i as u64 + 1);
        if mode == "one1m" && i + 1 == window {
            let pages: usize = m.alloc_census().slab.iter().map(|s| s.pages).sum();
            let r = sweep(&mut m); println!("one1m pages_before={pages} released={r}"); return;
        }
    }
    if mode == "one_m3" {
        let pages: usize = m.alloc_census().slab.iter().map(|s| s.pages).sum();
        let r = sweep(&mut m); println!("one_m3 pages_before={pages} released={r}"); return;
    }
    let pages: usize = m.alloc_census().slab.iter().map(|s| s.pages).sum();
    println!("{mode} sweeps={sweeps} released_total={released} pages_end={pages} held={}", m.len());
}
